    source: page.sources[locale], route: pagePath(page.id, locale),
    title: page.title[locale], description: page.description[locale],
    output: `src/content/docs${locales[locale].prefix}/docs/${page.id === 'docs' ? 'index' : page.id}.md`,
  })));
}
